DO $patch$ DECLARE d text; anchor text; BEGIN SELECT pg_get_functiondef('public.pm_validate_cutover_fixture()'::regprocedure) INTO d; anchor:='INSERT INTO public.pm_expenses(id,project_id,description,purchase_price,receipt_path,entity_id) VALUES(expense,p,''[QA DISPOSABLE] Expense'',100,path,''00000000-0000-4000-a000-000000000001'');'; IF position(anchor in d)=0 THEN RAISE EXCEPTION 'Fixture expense anchor missing'; END IF; d:=replace(d,anchor,'PERFORM set_config(''app.pe_action'',''1'',true); INSERT INTO public.pm_expenses(id,project_id,description,purchase_price,receipt_path,entity_id,workflow_version,original_currency,original_amount,eur_amount,rebill_mode,tax_treatment) VALUES(expense,p,''[QA DISPOSABLE] Expense'',100,path,''00000000-0000-4000-a000-000000000001'',2,''EUR'',100,100,''none'',''pending'');'); EXECUTE d; END $patch$;